with base as (select *, pressure - temp_c as pressure_minus_temp_c from device_readings where reading_ts > date '2025-09-01'), enriched as (select id, device_code, humidity, pressure, status_bits, last_value(temp_c) ignore nulls over (partition by device_code order by temp_c, id rows between unbounded preceding and current row) as last_known_temp_c, avg(temp_c) over (order by pressure, id rows between 6 preceding and current row) as temp_c_avg_6, lag(humidity, 1) over (partition by device_code order by temp_c, id) as prev_humidity from base where temp_c between 30 and 32), valid as (select *, floor(status_bits) as status_bits_whole from enriched where humidity >= 62), ranked as (select * from (select *, row_number() over (partition by device_code order by pressure desc nulls last, id) as rank_in_group from valid) x where rank_in_group = 1), scored as (select *, row_number() over (partition by device_code order by rank_in_group, id) as row_seq, lag(status_bits, 1) over (order by last_known_temp_c, id) as prev_status_bits, sum(pressure) over (partition by device_code order by status_bits_whole, id rows between unbounded preceding and current row) as cumulative_pressure from ranked) select id, device_code, humidity, pressure, status_bits, temp_c_avg_6, prev_humidity, status_bits_whole, prev_status_bits from scored order by prev_humidity desc;
